const weddingLanguages={en:'English',pt:'Português',es:'Español'};
const weddingURL='https://cheers.guru/destination-weddings/';
const weddingWhatsApp=text=>'https://wa.me/351927653087?text='+encodeURIComponent(text);
const weddingIcon='<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M20.5 11.7a8.5 8.5 0 0 1-12.6 7.5L3 21l1.7-4.8A8.5 8.5 0 1 1 20.5 11.7Z"/><path d="M8.3 7.5c.5 4.2 3 6.7 7.2 7.2l1-2-2.5-1-1 1c-1.4-.6-2.1-1.3-2.7-2.7l1-1-1-2.5Z"/></svg>';
function weddingInitialLanguage(){
 const explicit=new URLSearchParams(location.search).get('lang');
 if(weddingLanguages[explicit])return explicit;
 try{const saved=localStorage.getItem('cheers-language');if(weddingLanguages[saved])return saved;}catch{}
 return 'en';
}
function weddingSchema(lang){const t=weddingCopy[lang];return {'@context':'https://schema.org','@type':'Service',name:'Destination Wedding Cocktail Bar — Cheers Experiences',serviceType:'Wedding cocktail bar service',description:t.description,url:weddingURL+(lang==='en'?'':'?lang='+lang),areaServed:[{'@type':'Country',name:'Portugal'},{'@type':'Place',name:'Madeira'}],provider:{'@type':'Organization',name:'Cheers Experiences',legalName:'Sucesso Maciço, Lda.',url:'https://cheers.guru/',telephone:'+351927653087',email:'sucessomacico@gmail.com',knowsLanguage:['en','pt','es']}};}
function weddingMarkup(lang){
 const t=weddingCopy[lang];
 const chat=(label=t.wa,text=t.direct,cls='btn wedding-wa')=>`<a class="${cls}" href="${weddingWhatsApp(text)}" target="_blank" rel="noopener noreferrer">${weddingIcon}<span>${label}</span></a>`;
 const brand=`<a class="brand" href="/index.html?lang=${lang}" aria-label="Cheers Experiences"><b>Cheers</b><small>EXPERIENCES</small></a>`;
 return `<a class="skip" href="#main">${t.skip}</a><header class="header"><div class="wrap header-inner">${brand}<nav class="nav" id="navigation" aria-label="${t.nav}"><a href="/index.html?lang=${lang}">${premiumLabels[lang].hotels}</a><a href="/eventos.html?lang=${lang}">${premiumLabels[lang].events}</a><a href="/destination-weddings/?lang=${lang}" aria-current="page">${premiumLabels[lang].weddings}</a></nav><div class="language" aria-label="Language">${['pt','es','en'].map(l=>`<button type="button" data-lang="${l}" lang="${l}" aria-label="${weddingLanguages[l]}" aria-pressed="${l===lang}" class="${l===lang?'active':''}">${l.toUpperCase()}</button>`).join('')}</div><button class="menu-toggle" aria-controls="navigation" aria-expanded="false">${t.menu}</button></div></header>
 <main id="main"><section class="wedding-hero"><div class="wrap wedding-hero-grid"><div class="wedding-hero-copy"><span class="eyebrow">${t.eyebrow}</span><h1>${t.headline}</h1><p class="wedding-proposition">${t.proposition}</p><p class="wedding-intro">${t.intro}</p><div class="wedding-actions">${chat(t.cta)}<span class="wedding-micro">${t.hint}</span><a class="wedding-quote-link" href="#wedding-contact">${t.quote}</a></div></div><figure class="wedding-visual">${premiumImage("wedding-golden","",true)}</figure></div><div class="wrap wedding-location"><span>${t.strip[0]}</span><span>${t.strip[1]}</span></div></section>
 <section class="section wedding-usa" id="planning-from-usa"><div class="wrap split"><div><span class="eyebrow section-label">${t.usaLabel}</span><h2>${t.usaTitle}</h2></div><div><p class="event-lead">${t.usaText}</p><ul class="wedding-list">${t.usaPoints.map(x=>`<li>${x}</li>`).join('')}</ul><p class="section-note">${t.usaFoot}</p></div></div></section>
 <section class="section wedding-moments" id="celebrations"><div class="wrap"><span class="eyebrow section-label">${t.momentsLabel}</span><h2>${t.momentsTitle}</h2><div class="wedding-three">${t.moments.map((x,i)=>`<article><img class="moment-photo" src="/images/${['mojito-event-640','wedding-coast-640','citrus-cocktail'][i]}.webp" alt="" width="600" height="450" loading="lazy" decoding="async"><span class="wedding-number">0${i+1}</span><h3>${x[0]}</h3><h4>${x[1]}</h4><p>${x[2]}</p><a class="wedding-quote-link" data-moment="${i+1}" href="#wedding-contact">${t.quote}</a></article>`).join('')}</div></div></section>
 <section class="section wedding-services" id="your-bar"><div class="wrap split"><div class="wedding-service-intro"><span class="eyebrow">${t.serviceLabel}</span><h2>${t.serviceTitle}</h2><p>${t.serviceText}</p><img class="service-photo" src="/images/shaking.webp" width="577" height="380" alt="" loading="lazy" decoding="async">${chat()}</div><div class="wedding-service-list">${t.services.map((x,i)=>`<article><span>0${i+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></article>`).join('')}</div></div></section>
 <section class="section"><div class="wrap"><span class="eyebrow section-label">${t.planningLabel}</span><h2>${t.planningTitle}</h2><div class="wedding-three wedding-steps">${t.steps.map((x,i)=>`<article><span class="wedding-number">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></div></section>
 <section class="wedding-planners"><div class="wrap split"><h2>${t.plannerTitle}</h2><div><p>${t.plannerText}</p>${chat(t.plannerCTA,t.plannerMessage)}</div></div></section>
 <section class="section faq"><div class="wrap faq-layout"><h2>${t.faqTitle}</h2><div>${t.faqs.map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div></div></section>
 <section class="section contact wedding-contact" id="wedding-contact"><div class="wrap split"><div><span class="eyebrow">${t.contactLabel}</span><h2>${t.contactTitle}</h2><p class="contact-copy">${t.contactText}</p><div class="contact-links">${chat()}<a href="mailto:sucessomacico@gmail.com">sucessomacico@gmail.com</a><a href="tel:+351927653087">+351 927 653 087</a></div><p class="contact-note">${t.contactHint}</p></div><form id="wedding-form" class="contact-form"><h3>${t.formTitle}</h3><p class="fine">${t.required}</p><label>${t.name} *<input name="name" autocomplete="name" required maxlength="100"></label><label>${t.email}<input name="email" type="email" autocomplete="email" maxlength="150" aria-describedby="contact-rule"></label><label>${t.phone}<input name="phone" type="tel" autocomplete="tel" maxlength="50" aria-describedby="contact-rule"></label><p id="contact-rule" class="wedding-field-note">${t.contactRule}</p><div class="form-row"><label>${t.date}<input type="date" name="date"></label><label>${t.guests} *<input name="guests" type="number" inputmode="numeric" min="1" step="1" required></label></div><label>${t.venue} *<input name="venue" required maxlength="200" placeholder="${t.venuePlaceholder}"></label><label>${t.moment}<select name="moment">${t.choices.map((x,i)=>`<option value="${i}">${x}</option>`).join('')}</select></label><label>${t.message}<textarea name="message" rows="4" maxlength="1500" placeholder="${t.placeholder}"></textarea></label><button class="btn wedding-wa" type="submit">${weddingIcon}<span>${t.submit}</span></button><button class="wedding-email-button" type="submit" name="channel" value="email">${t.emailCTA}</button><p class="fine">${t.note}</p><div id="wedding-status" role="status" hidden><p>${t.status}</p><a id="wedding-retry" target="_blank" rel="noopener noreferrer">${t.retry}</a></div></form></div></section></main>
 <footer class="footer"><div class="wrap"><div class="footer-top">${brand}<p>${t.footer}</p><a href="/eventos.html?lang=${lang}">${t.events}</a><a href="/index.html?lang=${lang}">${t.hotels}</a></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Cheers Experiences</span><span>${t.legal}<br>${premiumLabels[lang].imageNote}</span></div></div></footer>${premiumContact(lang,"weddings")}`;
}
function weddingMessage(lang,data){const t=weddingCopy[lang],v=k=>String(data.get(k)||'').trim();return `${t.direct}\n\n${t.name}: ${v('name')}\n${t.email}: ${v('email')||'—'}\n${t.phone}: ${v('phone')||'—'}\n${t.date}: ${v('date')||'—'}\n${t.venue}: ${v('venue')}\n${t.guests}: ${v('guests')}\n${t.moment}: ${t.choices[Number(v('moment'))]||t.choices[0]}\n\n${v('message')}`;}
function renderWedding(lang){
 const previous={};document.querySelectorAll('#wedding-form [name]').forEach(e=>previous[e.name]=e.value);
 const t=weddingCopy[lang];document.documentElement.lang=lang==='pt'?'pt-PT':lang;document.title=t.title;
 document.querySelector('meta[name="description"]').content=t.description;
 const url=weddingURL+(lang==='en'?'':'?lang='+lang);
 for(const [key,value] of Object.entries({'og:title':t.title,'og:description':t.description,'og:url':url,'og:locale':{en:'en_US',pt:'pt_PT',es:'es_ES'}[lang]}))document.querySelector(`meta[property="${key}"]`).content=value;
 document.querySelector('link[rel="canonical"]').href=url;
 document.getElementById('structured-data').textContent=JSON.stringify(weddingSchema(lang));
 document.getElementById('wedding-app').innerHTML=weddingMarkup(lang);bindPremiumContact();
 document.querySelectorAll('#wedding-form [name]').forEach(e=>{if(previous[e.name]!==undefined)e.value=previous[e.name];});
 document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{const next=b.dataset.lang,u=new URL(location.href);u.searchParams.set('lang',next);history.replaceState(null,'',u);try{localStorage.setItem('cheers-language',next);}catch{}renderWedding(next);document.querySelector(`[data-lang="${next}"]`).focus({preventScroll:true});}));
 const nav=document.getElementById('navigation'),toggle=document.querySelector('.menu-toggle');
 const close=()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.textContent=t.menu;};
 toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?t.close:t.menu;});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));document.onkeydown=e=>{if(e.key==='Escape'&&nav.classList.contains('open')){close();toggle.focus();}};
 const form=document.getElementById('wedding-form');
 document.querySelectorAll('[data-moment]').forEach(a=>a.addEventListener('click',()=>{form.elements.moment.value=a.dataset.moment;}));
 const contactCheck=()=>form.elements.email.setCustomValidity(form.elements.email.value.trim()||form.elements.phone.value.trim()?'':t.contactRule);
 form.addEventListener('input',contactCheck);contactCheck();
 form.addEventListener('submit',e=>{e.preventDefault();contactCheck();if(!form.reportValidity())return;const message=weddingMessage(lang,new FormData(form));if(e.submitter?.value==='email'){location.href='mailto:sucessomacico@gmail.com?subject='+encodeURIComponent(t.subject)+'&body='+encodeURIComponent(message);return;}const url=weddingWhatsApp(message);const retry=document.getElementById('wedding-retry');retry.href=url;document.getElementById('wedding-status').hidden=false;window.open(url,'_blank','noopener,noreferrer');});
}
if(typeof document!=='undefined')renderWedding(weddingInitialLanguage());
